import { Controller, Get, Post, HttpCode, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

const ROLE = '예산·회계 담당자';
const DEFAULT_SIZE = 20;
const MAX_SIZE = 200;

function optText(v: unknown): string | null {
  if (v === undefined || v === null || v === '') {
    return null;
  }
  return String(v);
}

function optInt(v: unknown, label: string): string | null {
  const t = optText(v);
  if (t === null) {
    return null;
  }
  if (!/^-?\d+$/.test(t)) {
    throw new ApiError(400, 'VALIDATION_FAILED', label + ' 값은 정수여야 합니다.');
  }
  return t;
}

function reqInt(v: unknown, label: string): string {
  const t = optInt(v, label);
  if (t === null) {
    throw new ApiError(400, 'VALIDATION_FAILED', label + ' 값을 입력해 주세요.');
  }
  return t;
}

function reqAmount(v: unknown, label: string): string {
  if (typeof v !== 'number' && typeof v !== 'string') {
    throw new ApiError(400, 'VALIDATION_FAILED', label + ' 값을 입력해 주세요.');
  }
  const t = String(v).trim();
  if (!/^\d{1,16}(\.\d{1,2})?$/.test(t)) {
    throw new ApiError(400, 'VALIDATION_FAILED', label + ' 값은 0 이상의 금액이어야 합니다.');
  }
  return t;
}

async function changeStatus(
  db: { query: (sql: string, params: Record<string, unknown>) => Promise<any[]> },
  idText: string | undefined,
  from: string,
  to: string,
) {
  const id = reqInt(idText, '실행예산 ID');
  const rows = await db.query(
    'SELECT approval_status AS "approvalStatus" FROM budget_execution WHERE budget_execution_id = CAST(:id AS bigint) FOR UPDATE',
    { id },
  );
  if (rows.length === 0) {
    throw new ApiError(404, 'BUDGET_EXECUTION_NOT_FOUND', '실행예산을 찾을 수 없습니다.');
  }
  if (rows[0].approvalStatus !== from) {
    throw new ApiError(409, 'BUDGET_EXECUTION_STATUS_CONFLICT', '현재 상태에서는 처리할 수 없습니다.');
  }
  const updated = await db.query(
    'UPDATE budget_execution SET approval_status = :status, updated_at = now() WHERE budget_execution_id = CAST(:id AS bigint) RETURNING approval_status AS "approvalStatus"',
    { id, status: to },
  );
  return updated[0];
}

@Controller('api/v1')
export class FnSfr00303Controller {
  @Get('/budget-executions')
  async listBudgetExecutions(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const q = checks.queryOf(req.query);
    const accountingUnit = optText(q['accountingUnit']);
    const fiscalYear = optInt(q['fiscalYear'], '기수');
    const budgetGroup = optText(q['budgetGroup']);
    const budgetAccountId = optInt(q['budgetAccountId'], '예산과목');
    const projectId = optInt(q['projectId'], '프로젝트');
    const pageText = optInt(q['page'], 'page');
    const sizeText = optInt(q['size'], 'size');
    const page = pageText === null ? 0 : Number(pageText);
    const size = sizeText === null ? DEFAULT_SIZE : Number(sizeText);
    if (page < 0 || size < 1) {
      throw new ApiError(400, 'VALIDATION_FAILED', '쪽 번호와 크기가 올바르지 않습니다.');
    }
    const limit = Math.min(size, MAX_SIZE);
    const where =
      ' FROM budget_execution e JOIN budget_main m ON m.budget_main_id = e.budget_main_id' +
      ' WHERE (CAST(:accountingUnit AS varchar) IS NULL OR m.accounting_unit = CAST(:accountingUnit AS varchar))' +
      ' AND (CAST(:fiscalYear AS integer) IS NULL OR m.fiscal_year = CAST(:fiscalYear AS integer))' +
      ' AND (CAST(:budgetGroup AS varchar) IS NULL OR m.budget_group = CAST(:budgetGroup AS varchar))' +
      ' AND (CAST(:budgetAccountId AS bigint) IS NULL OR m.budget_account_id = CAST(:budgetAccountId AS bigint))' +
      ' AND (CAST(:projectId AS bigint) IS NULL OR m.project_id = CAST(:projectId AS bigint))';
    const filter = { accountingUnit, fiscalYear, budgetGroup, budgetAccountId, projectId };
    return transaction(async (db) => {
      const total = await db.query('SELECT COUNT(*) AS "total"' + where, filter);
      const items = await db.query(
        'SELECT e.budget_execution_id AS "budgetExecutionId", e.budget_main_id AS "budgetMainId",' +
          ' e.execution_month AS "executionMonth", e.execution_amount AS "executionAmount",' +
          ' e.approval_status AS "approvalStatus"' +
          where +
          ' ORDER BY e.budget_execution_id DESC LIMIT CAST(:limit AS integer) OFFSET CAST(:offset AS integer)',
        { ...filter, limit, offset: page * limit },
      );
      return { items, page, size: limit, total: Number(total[0].total) };
    });
  }

  @Post('/budget-executions')
  @HttpCode(200)
  async createBudgetExecution(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const data = checks.inputOf(req.body);
    const budgetMainId = reqInt(data['budgetMainId'], '본예산');
    const executionMonth = reqInt(data['executionMonth'], '편성월');
    const executionAmount = reqAmount(data['executionAmount'], '실행예산 금액');
    const month = Number(executionMonth);
    if (month < 1 || month > 12) {
      throw new ApiError(400, 'VALIDATION_FAILED', '편성월은 1~12 사이여야 합니다.');
    }
    return transaction(async (db) => {
      const mains = await db.query(
        'SELECT approval_status AS "approvalStatus" FROM budget_main WHERE budget_main_id = CAST(:budgetMainId AS bigint) FOR UPDATE',
        { budgetMainId },
      );
      if (mains.length === 0) {
        throw new ApiError(404, 'BUDGET_MAIN_NOT_FOUND', '기반 본예산을 찾을 수 없습니다.');
      }
      if (mains[0].approvalStatus !== '승인') {
        throw new ApiError(409, 'BUDGET_MAIN_NOT_APPROVED', '승인된 본예산이 아닙니다.');
      }
      const dup = await db.query(
        'SELECT 1 AS "x" FROM budget_execution WHERE budget_main_id = CAST(:budgetMainId AS bigint) AND execution_month = CAST(:executionMonth AS integer)',
        { budgetMainId, executionMonth },
      );
      if (dup.length > 0) {
        throw new ApiError(400, 'VALIDATION_FAILED', '이미 편성된 월입니다.');
      }
      // 가정: 본예산 범위 = 신청금액. 반려·승인 취소 건을 뺀 기존 편성액과 이번 금액의 합이 신청금액을 넘으면 거부한다.
      const range = await db.query(
        'SELECT (CAST(:executionAmount AS numeric) + COALESCE((SELECT SUM(execution_amount) FROM budget_execution' +
          ' WHERE budget_main_id = m.budget_main_id AND approval_status NOT IN (\'반려\', \'승인 취소\')), 0)) > m.requested_amount AS "exceeds"' +
          ' FROM budget_main m WHERE m.budget_main_id = CAST(:budgetMainId AS bigint)',
        { budgetMainId, executionAmount },
      );
      if (range[0].exceeds) {
        throw new ApiError(422, 'EXECUTION_AMOUNT_EXCEEDS_BUDGET', '월별 금액이 본예산 범위를 초과했습니다.');
      }
      const rows = await db.query(
        'INSERT INTO budget_execution (budget_main_id, execution_month, execution_amount, approval_status, created_at, updated_at)' +
          ' VALUES (CAST(:budgetMainId AS bigint), CAST(:executionMonth AS integer), CAST(:executionAmount AS numeric), \'신청\', now(), now())' +
          ' RETURNING budget_execution_id AS "budgetExecutionId", approval_status AS "approvalStatus"',
        { budgetMainId, executionMonth, executionAmount },
      );
      return rows[0];
    });
  }

  @Post('/budget-executions/:budgetExecutionId/close')
  @HttpCode(200)
  async closeBudgetExecution(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    return transaction(async (db) => changeStatus(db, req.params['budgetExecutionId'], '신청', '마감'));
  }

  @Post('/budget-executions/:budgetExecutionId/cancel-close')
  @HttpCode(200)
  async cancelCloseBudgetExecution(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    return transaction(async (db) => changeStatus(db, req.params['budgetExecutionId'], '마감', '마감 취소'));
  }

  @Post('/budget-executions/:budgetExecutionId/approve')
  @HttpCode(200)
  async approveBudgetExecution(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    return transaction(async (db) => changeStatus(db, req.params['budgetExecutionId'], '마감', '승인'));
  }

  @Post('/budget-executions/:budgetExecutionId/cancel-approval')
  @HttpCode(200)
  async cancelApprovalBudgetExecution(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    return transaction(async (db) => changeStatus(db, req.params['budgetExecutionId'], '승인', '승인 취소'));
  }
}

