import { useState } from 'react';
import {
  call,
  useData,
  Badge,
  Num,
  Filters,
  Band,
  DataTable,
  Pager,
  Drawer,
  Form,
  Field,
  TextInput,
  NumberInput,
  LookupSelect,
  RefName,
  ErrorText,
} from '../kit';
import type { PageProps, Row, Page } from '../kit';

const SIZE = 20;

const ACTIONS: Record<string, { label: string; path: string; note: string; done: string }> = {
  close: { label: '마감', path: 'close', note: '마감하면 전자결재 대상이 되고 마감 취소 전에는 수정할 수 없습니다.', done: '마감했습니다.' },
  cancelClose: { label: '마감 취소', path: 'cancel-close', note: '마감을 취소하면 마감 취소 상태가 됩니다.', done: '마감을 취소했습니다.' },
  approve: { label: '승인', path: 'approve', note: '승인하면 임의로 수정할 수 없고 승인 취소 절차를 거쳐야 합니다.', done: '승인했습니다.' },
  cancelApproval: { label: '승인 취소', path: 'cancel-approval', note: '승인을 취소하면 승인 취소 상태가 됩니다.', done: '승인을 취소했습니다.' },
};

function actionsOf(status: unknown): string[] {
  if (status === '신청') return ['close'];
  if (status === '마감') return ['cancelClose', 'approve'];
  if (status === '승인') return ['cancelApproval'];
  return [];
}

export default function FnSfr00303Page({ role, notify }: PageProps) {
  const [unit, setUnit] = useState('');
  const [year, setYear] = useState<number | string>('');
  const [projectId, setProjectId] = useState<number | string>('');
  const [applied, setApplied] = useState<Row>({});
  const [page, setPage] = useState(0);
  const [creating, setCreating] = useState(false);
  const [acting, setActing] = useState<{ row: Row; kind: string } | null>(null);
  const [mainId, setMainId] = useState<number | string>('');
  const [month, setMonth] = useState<number | string>('');
  const [amount, setAmount] = useState<number | string>('');
  const [message, setMessage] = useState('');

  const { data, error, loading, reload } = useData<Page>(
    () => call<Page>('GET', '/budget-executions', role, undefined, { ...applied, page, size: SIZE }),
    [applied, page],
  );

  function search() {
    setPage(0);
    setApplied({ accountingUnit: unit, fiscalYear: year, projectId });
  }

  function reset() {
    setUnit('');
    setYear('');
    setProjectId('');
    setPage(0);
    setApplied({});
  }

  async function create() {
    if (mainId === '' || month === '' || amount === '') {
      throw new Error('본예산, 편성월, 실행예산 금액을 모두 입력해 주세요.');
    }
    await call('POST', '/budget-executions', role, {
      budgetMainId: mainId,
      executionMonth: month,
      executionAmount: amount,
    });
    notify('실행예산을 신청했습니다.');
    setCreating(false);
    setMainId('');
    setMonth('');
    setAmount('');
    reload();
  }

  async function act() {
    if (!acting) return;
    const def = ACTIONS[acting.kind];
    await call('POST', '/budget-executions/' + String(acting.row['budgetExecutionId']) + '/' + def.path, role, {});
    notify(def.done);
    setActing(null);
    reload();
  }

  const columns = [
    { key: 'budgetMainId', label: '본예산', render: (r: Row) => <RefName table="budget_main" role={role} value={r['budgetMainId']} /> },
    { key: 'executionMonth', label: '편성월', render: (r: Row) => <span>{String(r['executionMonth'])}월</span> },
    { key: 'executionAmount', label: '실행예산 금액', render: (r: Row) => <Num value={r['executionAmount']} /> },
    { key: 'approvalStatus', label: '승인 처리 상태', render: (r: Row) => <Badge value={r['approvalStatus']} /> },
    {
      key: 'actions',
      label: '처리',
      render: (r: Row) => (
        <span>
          {actionsOf(r['approvalStatus']).map((k) => (
            <button key={k} className="ghost" onClick={() => { setMessage(''); setActing({ row: r, kind: k }); }}>
              {ACTIONS[k].label}
            </button>
          ))}
        </span>
      ),
    },
  ];

  return (
    <div>
      <h1>실행예산 편성·신청 및 마감</h1>
      <Filters onSearch={search} onReset={reset}>
        <Field label="회계단위">
          <TextInput value={unit} onChange={setUnit} />
        </Field>
        <Field label="기수(회계연도)">
          <NumberInput value={year} onChange={setYear} />
        </Field>
        <Field label="프로젝트">
          <LookupSelect table="project" role={role} value={projectId} onChange={setProjectId} />
        </Field>
      </Filters>
      <Band total={data?.total}>
        <button onClick={() => setCreating(true)}>실행예산 신청</button>
      </Band>
      {error ? <ErrorText text={error} /> : null}
      <DataTable
        columns={columns}
        rows={data?.items ?? []}
        empty={loading ? '불러오는 중입니다.' : '아직 등록한 내역이 없습니다. 실행예산 신청 버튼으로 첫 편성을 시작해 보세요.'}
      />
      <Pager page={page} size={SIZE} total={data?.total ?? 0} onPage={setPage} />
      {creating ? (
        <Drawer title="월별 실행예산 편성·신청" onClose={() => setCreating(false)}>
          <Form onSubmit={create} submit="신청">
            <Field label="본예산" required>
              <LookupSelect table="budget_main" role={role} value={mainId} onChange={setMainId} />
            </Field>
            <Field label="편성월" required hint="1~12 사이의 월">
              <NumberInput value={month} onChange={setMonth} />
            </Field>
            <Field label="실행예산 금액" required>
              <NumberInput value={amount} onChange={setAmount} />
            </Field>
          </Form>
        </Drawer>
      ) : null}
      {acting ? (
        <Drawer title={'실행예산 ' + ACTIONS[acting.kind].label} onClose={() => setActing(null)}>
          <Form
            onSubmit={act}
            submit={ACTIONS[acting.kind].label}
            danger={acting.kind === 'cancelClose' || acting.kind === 'cancelApproval'}
            note={ACTIONS[acting.kind].note}
          >
            <Field label="편성월" wide>
              <span>{String(acting.row['executionMonth'])}월</span>
            </Field>
            <Field label="실행예산 금액" wide>
              <Num value={acting.row['executionAmount']} />
            </Field>
          </Form>
          {message ? <ErrorText text={message} /> : null}
        </Drawer>
      ) : null}
    </div>
  );
}
